import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose2d_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> b,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv_transpose2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int Hin, int Win,
    int Cout, int Cout_per_group, int Cin_per_group, int groups,
    int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int Hout, int Wout)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 4;
  constexpr int CcPerBlock = 4;

  const int tid = threadIdx.x;
  const int n       = blockIdx.z;
  const int oc_tile = blockIdx.y;
  const int oc_base = oc_tile * CcPerBlock;

  const int P_total = Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // Per-channel group / ic_start (handles any CcPerBlock alignment correctly)
  int oc_of_cc[CcPerBlock];
  int oc_in_group_of_cc[CcPerBlock];
  int ic_start_of_cc[CcPerBlock];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int oc = oc_base + cc;
    oc_of_cc[cc] = oc;
    if (oc < Cout) {
      int grp = oc / Cout_per_group;
      oc_in_group_of_cc[cc] = oc % Cout_per_group;
      ic_start_of_cc[cc] = grp * Cin_per_group;
    } else {
      oc_in_group_of_cc[cc] = 0;
      ic_start_of_cc[cc] = 0;
    }
  }
  // Determine if all active output channels in this block share the same group
  // (same ic_start), enabling reuse of loaded X values across output channels.
  bool same_group = true;
  int common_ic_start = 0;
  {
    bool found = false;
    #pragma unroll
    for (int cc = 0; cc < CcPerBlock; ++cc) {
      if (oc_of_cc[cc] < Cout) {
        if (!found) {
          common_ic_start = ic_start_of_cc[cc];
          found = true;
        } else if (ic_start_of_cc[cc] != common_ic_start) {
          same_group = false;
        }
      }
    }
  }

  // CuTe global tensors
  int64_t sXn = (int64_t)Cin * Hin * Win;
  int64_t sXc = (int64_t)Hin * Win;
  int64_t sXh = (int64_t)Win;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, Hin, Win),
      make_stride(sXc, sXh, Int<1>{}));

  int64_t sYn = (int64_t)Cout * Hout * Wout;
  int64_t sYc = (int64_t)Hout * Wout;
  int64_t sYh = (int64_t)Wout;
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{}));

  // Weight tensor: [Cin, Cout_per_group, KH, KW]
  int64_t sWic = (int64_t)Cout_per_group * KH * KW;
  int64_t sWoc = (int64_t)KH * KW;
  int64_t sWkh = (int64_t)KW;
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout_per_group, KH, KW),
      make_stride(sWic, sWoc, sWkh, Int<1>{}));

  // Shared memory weight tile: [CcPerBlock, Cin_per_group, KH, KW]
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<CcPerBlock>{}, Cin_per_group, KH, KW),
      make_stride(Cin_per_group * KH * KW, KH * KW, KW, Int<1>{}));

  const int wtile_size = CcPerBlock * Cin_per_group * KH * KW;
  for (int idx = tid; idx < wtile_size; idx += Threads) {
    int kw = idx % KW;
    int tmp = idx / KW;
    int kh = tmp % KH;
    tmp /= KH;
    int ic = tmp % Cin_per_group;
    int cc = tmp / Cin_per_group;

    int oc = oc_of_cc[cc];
    T wval = T(0);
    if (oc < Cout) {
      int ic_global = ic_start_of_cc[cc] + ic;
      if (ic_global < Cin) {
        wval = mW(ic_global, oc_in_group_of_cc[cc], kh, kw);
      }
    }
    sW(cc, ic, kh, kw) = wval;
  }
  __syncthreads();

  // Precompute output positions handled by this thread
  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / Wout;
      ow_arr[i] = p - oh_arr[i] * Wout;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  float acc[CcPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int oc = oc_of_cc[cc];
    float bval = 0.0f;
    if (B != nullptr && oc < Cout) {
      bval = (float)B[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_idx[i];
    if (p >= P_total) continue;
    int oh = oh_arr[i];
    int ow = ow_arr[i];

    for (int kh = 0; kh < KH; ++kh) {
      int ih_num = oh + pad_h - kh * dil_h;
      if (ih_num % stride_h != 0) continue;
      int ih = ih_num / stride_h;
      if (ih < 0 || ih >= Hin) continue;

      for (int kw = 0; kw < KW; ++kw) {
        int iw_num = ow + pad_w - kw * dil_w;
        if (iw_num % stride_w != 0) continue;
        int iw = iw_num / stride_w;
        if (iw < 0 || iw >= Win) continue;

        if (same_group) {
          #pragma unroll 1
          for (int ic = 0; ic < Cin_per_group; ++ic) {
            int ic_global = common_ic_start + ic;
            float xval = (float)mX(ic_global, ih, iw);
            #pragma unroll
            for (int cc = 0; cc < CcPerBlock; ++cc) {
              int oc = oc_of_cc[cc];
              if (oc >= Cout) continue;
              float wval = (float)sW(cc, ic, kh, kw);
              acc[cc][i] += xval * wval;
            }
          }
        } else {
          #pragma unroll
          for (int cc = 0; cc < CcPerBlock; ++cc) {
            int oc = oc_of_cc[cc];
            if (oc >= Cout) continue;
            int ic_start = ic_start_of_cc[cc];
            float local_acc = 0.0f;
            for (int ic = 0; ic < Cin_per_group; ++ic) {
              int ic_global = ic_start + ic;
              float xval = (float)mX(ic_global, ih, iw);
              float wval = (float)sW(cc, ic, kh, kw);
              local_acc += xval * wval;
            }
            acc[cc][i] += local_acc;
          }
        }
      }
    }
  }

  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int oc = oc_of_cc[cc];
    if (oc >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(oc, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv_transpose2d_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> b,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups)
{
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cin, Cout/groups, KH, KW]");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t Hin = x.size(2);
  int64_t Win = x.size(3);

  TORCH_CHECK(w.size(0) == Cin, "w.size(0) must equal Cin");
  int64_t Cout_per_group = w.size(1);
  int64_t KH = w.size(2);
  int64_t KW = w.size(3);
  int64_t Cout = Cout_per_group * groups;
  int64_t Cin_per_group = Cin / groups;

  TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride must be > 0");
  TORCH_CHECK(dil_h > 0 && dil_w > 0, "dilation must be > 0");
  TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding must be >= 0");

  int64_t Hout = (Hin - 1) * stride_h - 2 * pad_h + dil_h * (KH - 1) + 1;
  int64_t Wout = (Win - 1) * stride_w - 2 * pad_w + dil_w * (KW - 1) + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 4;
  constexpr int CcPerBlock = 4;
  const int64_t P_total = Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + CcPerBlock - 1) / CcPerBlock),
      (unsigned)N
  );

  size_t smem_bytes = (size_t)CcPerBlock * Cin_per_group * KH * KW * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv_transpose2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)Hin, (int)Win,
      (int)Cout, (int)Cout_per_group, (int)Cin_per_group, (int)groups,
      (int)KH, (int)KW,
      stride_h, stride_w,
      pad_h, pad_w,
      dil_h, dil_w,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv_transpose2d_ext = load_inline(
    name="cute_conv_transpose2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Grouped, dilated, strided, padded 2D transposed convolution implemented with
    a single custom CUDA kernel using CuTe tensors for indexing.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1), padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        KH, KW = kernel_size
        Cout_per_group = out_channels // groups

        # Weight layout matches nn.ConvTranspose2d: [in_channels, out_channels/groups, KH, KW]
        self.weight = nn.Parameter(torch.empty(in_channels, Cout_per_group, KH, KW))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv_transpose2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels // self.groups
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        stride_h, stride_w = self.stride
        pad_h, pad_w = self.padding
        dil_h, dil_w = self.dilation
        return self._ext.conv_transpose2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(stride_h), int(stride_w),
            int(pad_h), int(pad_w),
            int(dil_h), int(dil_w),
            int(self.groups),
        )

