      make_shape(Cin, Cout_per_group, KH, KW),
      make_stride(sWic, sWoc, sWkh, Int<1>{}));

  // Shared memory weight tile: [CcPerBlock, Cin_per_group, KH, KW]
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  auto sW = make_tensor(
